ftth=@{title='FTTH-Abschluss – reales Foto';url='https://commons.wikimedia.org/wiki/Special:Redirect/file/Fiber_to_the_Home-aansluiting_van_E-fiber.jpg';filename='ftth-abschluss-reales-foto.jpg';mime='image/jpeg';alt='Realer FTTH-Glasfaserabschluss an einer Wand';caption='Foto: Maxmust / Wikimedia Commons / CC BY-SA 4.0';description='Reales FTTH-Foto. Quelle: Wikimedia Commons, CC BY-SA 4.0.'}
