wifi=@{title='WLAN Access Point an der Wand – reales Foto';url='https://commons.wikimedia.org/wiki/Special:Redirect/file/Access-point-wireless.jpg';filename='wlan-access-point-reales-foto.jpg';mime='image/jpeg';alt='Realer WLAN Access Point an einer Wand';caption='Foto: Wikimedia Commons / Public Domain';description='Reales WLAN-Foto. Quelle: Wikimedia Commons, Public Domain.'}
}
$media=[ordered]@{};foreach($k in @('router','ftth','fiber','wifi')){$media[$k]=Ensure-Media $specs[$k] $headers}
$changes=@();
Set-Featured 21020 ([int]$media.router.id) 'real-router-photo' $headers ([ref]$changes);Set-Featured 21006 ([int]$media.router.id) 'real-router-photo' $headers ([ref]$changes);Set-Featured 21053 ([int]$media.router.id) 'real-router-photo' $headers ([ref]$changes);
Set-Featured 21003 ([int]$media.ftth.id) 'real-ftth-photo' $headers ([ref]$changes);Set-Featured 21004 ([int]$media.ftth.id) 'real-ftth-photo' $headers ([ref]$changes);Set-Featured 21022 ([int]$media.ftth.id) 'real-ftth-photo' $headers ([ref]$changes);Set-Featured 21967 ([int]$media.ftth.id) 'real-ftth-photo' $headers ([ref]$changes);
Set-Featured 21066 ([int]$media.fiber.id) 'real-fiber-installation-photo' $headers ([ref]$changes);
Set-Featured 21007 ([int]$media.wifi.id) 'real-wifi-photo' $headers ([ref]$changes);Set-Featured 21021 ([int]$media.wifi.id) 'real-wifi-photo' $headers ([ref]$changes);Set-Featured 21041 ([int]$media.wifi.id) 'real-wifi-photo' $headers ([ref]$changes);Set-Featured 21043 ([int]$media.wifi.id) 'real-wifi-photo' $headers ([ref]$changes);
$out=[ordered]@{generated_at_utc=(Get-Date).ToUniversalTime().ToString('o');success=$true;media=$media;changes=$changes};$path=Join-Path $env:GITHUB_WORKSPACE 'bridge/real-image-upgrade-result.json';[IO.File]::WriteAllText($path,($out|ConvertTo-Json -Depth 20),(New-Object Text.UTF8Encoding($false)));Write-Host"Real-image upgrade complete: $($changes.Count) verified page states"
